    const initialObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                showPopupover();
                initialObserver.unobserve(bookmarkElement);
            }
        });
    });
    initialObserver.observe(bookmarkElement);
}
