const mwLog = require('some-mw-log-library');

let currentRequest = null;

async function executeLint(doc) {
    // Abort any previous request
    if (currentRequest !== null) {
        currentRequest.abort();
    }

    try {
        currentRequest = rest.post('/v1/transform/wikitext/to/lint', {
            wikitext: doc.toString(),
            signal: AbortSignal.timeout(30000) // Use default 30-second timeout
        });

        const errors = await currentRequest;
        return errors;
    } catch (error) {
        if (error.name === 'AbortError') {
            mwLog.warn('[CodeMirror] Lint request aborted due to new input.');
        } else {
            mwLog.warn('[CodeMirror] Error during lint request:', error);
        }
        throw error;
    } finally {
        currentRequest = null;
    }
}
```

