function checkFeatureAvailability(userMode) {
    // Define feature availability based on user mode
    const featureAvailability = {
        base: ['featureA', 'featureB'],
        beta: ['featureA', 'featureB', 'featureC'],
        alpha: ['featureA', 'featureB', 'featureC', 'featureD']
    };

    // Get the list of features available for the given user mode
    const availableFeatures = featureAvailability[userMode] || [];

